 const green=materials.plastic(0x2b5b40,{roughness:.9}),dark=materials.plastic(0x1b211d,{roughness:.87}),tin=materials.metal(0xb6b9a6),gold=materials.metal(0xbda063),top=spec.pcb.topZ,pcb=solid(host.body,s,.8,[0,0,top-.8],green,'NBIoT-CN own inferred shaped carrier PCB with native boss reliefs/Grove solder bores'),pads=[],barrels=[];
