 const module=slab(host.body,17.6,15.7,.55,.08,spec.module.position,dark,[],0);module.name='NBIoT-CN exact SIM7020C LCC module substrate,hidden installation inferred';const shield=slab(host.body,16.9,15.0,1.75,.16,[0,-3,top+.55],materials.metal(0xbec2b5,{roughness:.64}),[],.035);shield.name='NBIoT-CN own SIM7020C fixed shield envelope,height inferred';const lands=[];for(const side of[-1,1])for(let i=0;i<11;i++)lands.push(mesh(host.body,new THREE.BoxGeometry(.7,.45,.08),gold,[side*8.55,-3+(i-5)*1.25,top+.04],'NBIoT-CN SIM7020C perimeter land appearance,notpinmapping'));
