export function buildNbiotCN(host,{rearCover=true,antenna=false,antennaAngleDeg=0}={}){if(typeof rearCover!=='boolean'||typeof antenna!=='boolean')throw new TypeError('rearCover/antenna must be boolean');if(!Number.isFinite(antennaAngleDeg)||antennaAngleDeg<0||antennaAngleDeg>90)throw new RangeError('antennaAngleDeg must be0…90');const parts=addCadParts(host,data.filter(p=>rearCover||p.role==='front'),{shell:materials.plastic(0x454943,{roughness:.88})}),board=carrier(host),socket=grove(host),rf=sma(host),holder=sim(host,!rearCover),radio=feedline(host),screws=rearCover?fixing(host):[],films={};for(const face of rearCover?['front','back']:['front']){const l=spec.labels[face],film=slab(host.body,...l.size,.07,.1,l.position,materials.plastic(0xd9dbd5,{roughness:.83}),[],0);film.name='NBIoT-CN independent real '+face+' silver labelsubstrate';film.userData={role:'physical-label-substrate',face};films[face]=film;}host.nbiotCnAssembly={rearCover,parts,board,socket,sma:rf,sim:holder,radio,screws,films};host.unitStickers=addStickers(host);if(antenna)rf.port.attach(new Antenna({angleDeg:antennaAngleDeg}));}
